# --------------------------------------------------------------------------
# LOGGING
# --------------------------------------------------------------------------

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(threadName)s: %(message)s",
)
log = logging.getLogger("dhan_downloader")

# --------------------------------------------------------------------------
# GLOBAL RATE LIMITER
# --------------------------------------------------------------------------

class RateLimiter:
    def __init__(self, max_per_sec: int):
        self.min_interval = 1.0 / max_per_sec
        self._lock = threading.Lock()
        self._last_call = 0.0

    def wait(self):
        with self._lock:
            now = time.monotonic()
            elapsed = now - self._last_call
            sleep_for = self.min_interval - elapsed
            if sleep_for > 0:
                time.sleep(sleep_for)
            self._last_call = time.monotonic()

rate_limiter = RateLimiter(MAX_REQUESTS_PER_SEC)

# --------------------------------------------------------------------------
# INSTRUMENT MASTER (SECURITY_ID -> trading symbol resolution)
# --------------------------------------------------------------------------
def load_instrument_master() -> pd.DataFrame:
    """Download (or load cached) Dhan scrip master, filtered strictly to NSE Equity."""
    if os.path.exists(SCRIP_MASTER_CACHE):
        age_hours = (time.time() - os.path.getmtime(SCRIP_MASTER_CACHE)) / 3600
        if age_hours < 24:
            log.info("Using cached instrument master (%.1fh old).", age_hours)
            return pd.read_csv(SCRIP_MASTER_CACHE, low_memory=False)

    log.info("Downloading NSE instrument master from Dhan...")
    resp = requests.get(SCRIP_MASTER_URL, timeout=60)
    resp.raise_for_status()
    df = pd.read_csv(io.StringIO(resp.text), low_memory=False)

    # Apply strict filters to keep only Cash Equities
    if "SEM_EXM_EXCH_ID" in df.columns:
        df = df[df["SEM_EXM_EXCH_ID"] == "NSE"]
    if "SEM_SEGMENT" in df.columns:
        df = df[df["SEM_SEGMENT"] == "E"]
    if "SEM_INSTRUMENT_NAME" in df.columns:
        df = df[df["SEM_INSTRUMENT_NAME"] == "EQUITY"]
    if "SEM_EXCH_INSTRUMENT_TYPE" in df.columns:
        df = df[df["SEM_EXCH_INSTRUMENT_TYPE"] == "ES"]

    df.to_csv(SCRIP_MASTER_CACHE, index=False)
    log.info("Instrument master cached to %s (%d NSE Equity rows).", SCRIP_MASTER_CACHE, len(df))
    return df

def build_security_id_symbol_map(master_df: pd.DataFrame) -> dict:
    """Map SEM_SMST_SECURITY_ID -> SEM_TRADING_SYMBOL for filename lookups."""
    id_col = "SEM_SMST_SECURITY_ID" if "SEM_SMST_SECURITY_ID" in master_df.columns else None
    sym_col = "SEM_TRADING_SYMBOL" if "SEM_TRADING_SYMBOL" in master_df.columns else None
    if not id_col or not sym_col:
        log.warning("Could not find expected columns in scrip master; symbol names will fall back to security_id.")
        return {}
    return dict(zip(master_df[id_col].astype(str), master_df[sym_col].astype(str)))

# --------------------------------------------------------------------------
# SECURITY ID LIST LOADING (Enforcing Equity Parameters)
# --------------------------------------------------------------------------

def load_security_ids() -> list:
    if not SECURITY_IDS:
        sys.exit("ERROR: The SECURITY_IDS list in code is empty.")

    # Explicitly force NSE_EQ and EQUITY for every hardcoded security ID
    rows = [
        {
            "security_id": str(sid).strip(),
            "exchange_segment": "NSE_EQ",
            "instrument": "EQUITY",
        }
        for sid in SECURITY_IDS
    ]
    log.info("=== Using SECURITY_IDs from code configuration (Equity Only) ===")
    log.info("IDs: %s", ", ".join(r["security_id"] for r in rows))
    return rows

# --------------------------------------------------------------------------
# DATE CHUNKING + CLI ARGS
# --------------------------------------------------------------------------

def parse_date_args() -> tuple:
    parser = argparse.ArgumentParser(description="Dhan 5-min OHLCV bulk downloader")
    parser.add_argument("--start", type=str, default=None, help="Start date, YYYY-MM-DD")
    parser.add_argument("--end", type=str, default=None, help="End date, YYYY-MM-DD")
    args = parser.parse_args()

    today = datetime.now().date()
    end = datetime.strptime(args.end, "%Y-%m-%d").date() if args.end else today
    start = datetime.strptime(args.start, "%Y-%m-%d").date() if args.start else (end - timedelta(days=365 * DEFAULT_YEARS_BACK))

    if start >= end:
        sys.exit(f"ERROR: --start ({start}) must be before --end ({end}).")

    return start, end

def build_date_chunks(start: date, end: date, chunk_days: int):
    chunks = []
    cursor = start
    while cursor < end:
        chunk_end = min(cursor + timedelta(days=chunk_days), end)
        chunks.append((cursor, chunk_end))
        cursor = chunk_end + timedelta(days=1)
    return chunks

# --------------------------------------------------------------------------
# API CALL WITH RETRY
# --------------------------------------------------------------------------

def fetch_intraday_chunk(security_id: str, exchange_segment: str, instrument: str,
                         from_date: str, to_date: str) -> dict:
    headers = {
        "access-token": DHAN_ACCESS_TOKEN,
        "client-id": DHAN_CLIENT_ID,
        "Content-Type": "application/json",
    }
    payload = {
        "securityId": security_id,
        "exchangeSegment": exchange_segment,
        "instrument": instrument,
        "interval": INTERVAL,
        "fromDate": from_date,
        "toDate": to_date,
    }

    for attempt in range(1, MAX_RETRIES + 1):
        rate_limiter.wait()
        try:
            resp = requests.post(INTRADAY_ENDPOINT, headers=headers, json=payload, timeout=30)
        except requests.RequestException as e:
            log.warning("[%s] network error (attempt %d/%d): %s", security_id, attempt, MAX_RETRIES, e)
            time.sleep(RETRY_BACKOFF_BASE ** attempt)
            continue

        if resp.status_code == 200:
            return resp.json()

        if resp.status_code == 429:
            wait_s = RETRY_BACKOFF_BASE ** attempt
            log.warning("[%s] rate limited (429), backing off %.1fs", security_id, wait_s)
            time.sleep(wait_s)
            continue

        if 500 <= resp.status_code < 600:
            wait_s = RETRY_BACKOFF_BASE ** attempt
            log.warning("[%s] server error %d, retrying in %.1fs", security_id, resp.status_code, wait_s)
            time.sleep(wait_s)
            continue

        log.error("[%s] request failed: %d %s | from=%s to=%s",
                   security_id, resp.status_code, resp.text[:300], from_date, to_date)
        return {}

    log.error("[%s] giving up after %d attempts", security_id, MAX_RETRIES)
    return {}

# --------------------------------------------------------------------------
# PER-SYMBOL DOWNLOAD
# --------------------------------------------------------------------------

def download_symbol(sec_info: dict, symbol_map: dict, date_chunks: list) -> str:
    security_id = sec_info["security_id"]
    exchange_segment = "NSE_EQ"
    instrument = "EQUITY"
    
    # If the ID maps to an option string because it wasn't filtered, 
    # force it to use the security_id or drop it if it's not a pure equity symbol.
    symbol_name = symbol_map.get(security_id, security_id)
    if "-" in str(symbol_name):  # Catches option/future naming patterns like GBPINR-Jul2025-...
        log.warning("[%s] Skipped non-equity mapping detected: %s", security_id, symbol_name)
        return ""

    out_path = os.path.join(OUTPUT_DIR, f"{symbol_name}_{security_id}.csv")
    
    if os.path.exists(out_path):
        log.info("[%s] output already exists, skipping (%s).", symbol_name, out_path)
        return out_path

    all_rows = []
    for from_d, to_d in date_chunks:
        from_str, to_str = from_d.isoformat(), to_d.isoformat()
        data = fetch_intraday_chunk(security_id, exchange_segment, instrument, from_str, to_str)

        if not data or "timestamp" not in data or not data["timestamp"]:
            log.info("[%s] no data for %s -> %s", symbol_name, from_str, to_str)
            continue

        chunk_df = pd.DataFrame({
            "symbol": symbol_name,
            "security_id": security_id,
            "timestamp": data["timestamp"],
            "open": data.get("open", []),
            "high": data.get("high", []),
            "low": data.get("low", []),
            "close": data.get("close", []),
            "volume": data.get("volume", []),
        })
        all_rows.append(chunk_df)

    if not all_rows:
        log.warning("[%s] no data retrieved for the requested date range.", symbol_name)
        return ""

    full_df = pd.concat(all_rows, ignore_index=True)
    full_df["timestamp"] = pd.to_datetime(full_df["timestamp"], unit="s") \
        .dt.tz_localize("UTC").dt.tz_convert("Asia/Kolkata").dt.tz_localize(None)
    full_df = full_df.drop_duplicates(subset=["security_id", "timestamp"]).sort_values("timestamp")
    full_df = full_df[["symbol", "security_id", "timestamp", "open", "high", "low", "close", "volume"]]

    os.makedirs(OUTPUT_DIR, exist_ok=True)
    full_df.to_csv(out_path, index=False)
    log.info("[%s] saved %d rows -> %s", symbol_name, len(full_df), out_path)
    return out_path

def main():
    os.makedirs(OUTPUT_DIR, exist_ok=True)

    start_date, end_date = parse_date_args()

    # Load instrument master to map Security IDs to Trading Symbols
    master_df = load_instrument_master()
    symbol_map = build_security_id_symbol_map(master_df)

    security_list = load_security_ids()

    date_chunks = build_date_chunks(start_date, end_date, CHUNK_DAYS)
    log.info("Date range: %s -> %s | %d chunks per symbol.", start_date, end_date, len(date_chunks))
    log.info("Total symbols to process: %d", len(security_list))

    results = []
    with ThreadPoolExecutor(max_workers=MAX_WORKERS, thread_name_prefix="sym") as pool:
        futures = {
            pool.submit(download_symbol, sec, symbol_map, date_chunks): sec["security_id"]
            for sec in security_list
        }
        for fut in as_completed(futures):
            sec_id = futures[fut]
            try:
                path = fut.result()
                results.append((sec_id, path))
            except Exception as e:
                log.error("[%s] failed with exception: %s", sec_id, e)
                results.append((sec_id, ""))

    ok = sum(1 for _, p in results if p)
    log.info("Done. %d/%d symbols downloaded successfully.", ok, len(results))

if __name__ == "__main__":
    main()